signature.code:
useCollection<T>(config: {
  getId: (entity: T) => string;
  sortBy?: (a: T, b: T) => number;
}): {
  items: T[];
  count: number;
  version: number;
  status, isLoading, error;
  addOne, addMany, setAll,
  updateOne, updateMany,
  upsertOne, upsertMany,
  removeOne, removeMany, removeAll,
  getResource, getById,
  collection: Collection<T>;
}

examples.code:
// Collection  ≈  Map<id, T> + id[]
// getResource(id) ≈ createResource({ initialData: entity, save: draft => updateOne(id, draft) })
//
// List re-renders on version++
// Row inputs use useField(resource, path) → only that row re-renders on keystrokes

import { useCollection } from 'qortex-resource-react';

type Todo = { id: string; title: string; done: boolean };

function TodoList() {
  const { items, addOne, removeOne, updateOne, count } = useCollection<Todo>({
    getId: (t) => t.id,
    sortBy: (a, b) => Number(a.done) - Number(b.done), // incomplete first
  });

  return (
    <div>
      <p>{count} tasks</p>
      <button
        type="button"
        onClick={() =>
          addOne({ id: crypto.randomUUID(), title: 'New', done: false })
        }
      >
        Add
      </button>
      <ul>
        {items.map((t) => (
          <li key={t.id}>
            <input
              type="checkbox"
              checked={t.done}
              onChange={(e) => updateOne(t.id, { done: e.target.checked })}
            />
            {t.title}
            <button type="button" onClick={() => removeOne(t.id)}>×</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

function ProjectTasks({ projectId }: { projectId: string }) {
  // Remount when project changes → fresh empty collection
  return <TaskList key={projectId} projectId={projectId} />;
}

function TaskList({ projectId }: { projectId: string }) {
  const { items, setAll, isLoading, error } = useCollection<Task>({
    getId: (t) => t.id,
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    api.tasks
      .list(projectId)
      .then((rows) => {
        if (!cancelled) setAll(rows);
      })
      .catch((e) => {
        if (!cancelled) console.error(e);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [projectId, setAll]);

  if (loading) return <p>Loading…</p>;
  return <TaskTable items={items} />;
}

import { useCollection, useField } from 'qortex-resource-react';
import type { Resource } from 'qortex-resource';

function EditableList() {
  const { items, setAll, addOne, removeOne, getResource } = useCollection<Todo>({
    getId: (t) => t.id,
  });

  useEffect(() => {
    api.todos.list().then(setAll);
  }, [setAll]);

  return (
    <ul>
      {items.map((t) => (
        <TodoRow
          key={t.id}
          resource={getResource(t.id)}
          onRemove={() => removeOne(t.id)}
        />
      ))}
      <button
        type="button"
        onClick={() =>
          addOne({ id: crypto.randomUUID(), title: '', done: false })
        }
      >
        Add row
      </button>
    </ul>
  );
}

function TodoRow({
  resource,
  onRemove,
}: {
  resource: Resource<Todo>;
  onRemove: () => void;
}) {
  const title = useField(resource, 'title');
  const done = useField(resource, 'done');
  const dirty = resource.snapshot.isChanged;

  return (
    <li>
      <input
        type="checkbox"
        checked={!!done.value}
        onChange={(e) => done.onChange(e.target.checked)}
      />
      <input
        value={title.value ?? ''}
        onChange={(e) => title.onChange(e.target.value)}
        onBlur={title.onBlur}
      />
      <button
        type="button"
        disabled={!dirty}
        onClick={async () => {
          // 1) commit draft into the collection
          const result = await resource.save();
          if (!result.ok) return;
          // 2) optional: persist to API
          const entity = resource.snapshot.data!;
          await api.todos.update(entity.id, entity);
        }}
      >
        Save
      </button>
      <button type="button" disabled={!dirty} onClick={() => resource.resetDraft()}>
        Discard
      </button>
      <button type="button" onClick={onRemove}>Delete</button>
    </li>
  );
}

function BulkActions() {
  const { items, updateMany, removeMany, removeAll } = useCollection<Todo>({
    getId: (t) => t.id,
  });

  const selectedIds = items.filter((t) => t.done).map((t) => t.id);

  return (
    <>
      <button
        type="button"
        onClick={() => updateMany(selectedIds, { done: false })}
      >
        Mark incomplete
      </button>
      <button type="button" onClick={() => removeMany(selectedIds)}>
        Delete completed
      </button>
      <button type="button" onClick={() => removeAll()}>
        Clear all
      </button>
    </>
  );
}

const { updateOne } = useCollection<Todo>({ getId: (t) => t.id });

// Merge patch
updateOne('1', { title: 'Renamed' });

// Functional — based on previous entity
updateOne('1', (prev) => ({
  ...prev,
  title: prev.title.toUpperCase(),
}));

function OpenTasks() {
  const { items, collection, version } = useCollection<Todo>({
    getId: (t) => t.id,
  });

  // version in deps keeps this honest if you memoize
  const open = useMemo(
    () => collection.selectWhere((t) => !t.done),
    [collection, version],
  );

  // Or simply:
  const openSimple = items.filter((t) => !t.done);

  return <ul>{open.map((t) => <li key={t.id}>{t.title}</li>)}</ul>;
}

useCollection<Task>({
  getId: (t) => t.id,
  sortBy: (a, b) => {
    // priority desc, then title asc
    if (a.priority !== b.priority) return b.priority - a.priority;
    return a.title.localeCompare(b.title);
  },
});
// After every add/update/setAll, ids are re-sorted

const { getById, getResource } = useCollection<Todo>({ getId: (t) => t.id });

getById('1');        // plain entity snapshot (or undefined)
getResource('1');    // Resource for editing — cached until remove/setAll/destroy

// Safe pattern: only call getResource for ids that exist in items
items.map((t) => getResource(t.id));
